export const instructions = {"en":[{"title":"Cut","action":"Cut the outside line, including the edge strips and the antenna clubs. Cut the four short slits at the back of the hindwings.","check":"One piece. Each hindwing has a tab between two slits."},{"title":"Score","action":"Lay a ruler on each dashed line and press along it with an empty ballpoint pen.","check":"Every fold line shows a groove. Thick paper now folds cleanly."},{"title":"Fold the costa","action":"Fold each edge strip under its wing along its dashed line. Press it flat.","check":"The front edge is straight and doubled, like the costa vein of a real wing."},{"title":"Fold the body","action":"Fold in half on the dashed centre line, colors inside. Then fold each wing back out on its dash-dot line.","check":"The two body layers hang underneath and touch."},{"title":"Clip the head","action":"Slide both clips onto the head over the two body layers, one on top of the other, all the way to the nose.","check":"The clips stay inside the dashed clip box."},{"title":"Balance","action":"Rest the wings on two fingertips under the ringed dots. Tail drops: add a clip. Nose drops: slide a clip back, or remove one.","check":"It stays level on your fingers."},{"title":"Set the V","action":"Lift both wings into a shallow V. Look from the tail and compare each wingtip with the strip.","check":"Both tips are the same height."},{"title":"Launch and trim","action":"Push it smoothly forward, nose level, about as fast as a jog. Dives: bend both tabs up 1–2 mm. Swoops up and stalls: flatten them.","check":"Turns left: bend the right tab up a little. Turns right: the left tab."}],"es":[{"title":"Recorta","action":"Recorta la línea exterior, con las tiras del borde y las puntas de las antenas. Corta las cuatro ranuras cortas de las alas traseras.","check":"Es una sola pieza. Cada ala trasera tiene una aleta entre dos ranuras."},{"title":"Marca los dobleces","action":"Apoya una regla en cada línea discontinua y repásala con un bolígrafo sin tinta.","check":"Cada doblez tiene un surco. El papel grueso se dobla limpio."},{"title":"Dobla la costa","action":"Dobla cada tira del borde debajo de su ala por su línea de trazos. Aplánala bien.","check":"El borde delantero queda recto y doble, como la vena costal de un ala real."},{"title":"Dobla el cuerpo","action":"Dobla por la mitad en la línea central de trazos, con los colores dentro. Luego dobla cada ala hacia fuera por su línea de trazo y punto.","check":"Las dos capas del cuerpo cuelgan debajo y se tocan."},{"title":"Pon los clips en la cabeza","action":"Desliza los dos clips sobre las dos capas del cuerpo, uno encima del otro, hasta la punta.","check":"Los clips quedan dentro del recuadro de trazos."},{"title":"Equilibra","action":"Apoya las alas en dos dedos bajo los puntos con anillo. Si cae la cola, añade un clip. Si cae la cabeza, retrasa un clip o quítalo.","check":"Se queda horizontal sobre tus dedos."},{"title":"Forma la V","action":"Sube las dos alas en una V suave. Mira desde la cola y compara cada punta con la tira.","check":"Las dos puntas están a la misma altura."},{"title":"Lanza y ajusta","action":"Empújala con suavidad hacia delante, con la punta recta, a la velocidad de un trote. Si cae en picado, sube las dos aletas 1–2 mm. Si sube y se frena, aplánalas.","check":"Gira a la izquierda: sube un poco la aleta derecha. Gira a la derecha: la izquierda."}],"ru":[{"title":"Вырежи","action":"Вырежи по внешней линии, вместе с полосками края и булавами усиков. Сделай четыре коротких надреза сзади на задних крыльях.","check":"Одна деталь. На каждом заднем крыле есть закрылок между двумя надрезами."},{"title":"Продави сгибы","action":"Приложи линейку к каждой пунктирной линии и проведи по ней пустой шариковой ручкой.","check":"На каждой линии сгиба есть бороздка. Плотная бумага сгибается ровно."},{"title":"Согни край крыла","action":"Загни каждую полоску края под крыло по её пунктирной линии. Прижми.","check":"Передний край прямой и двойной, как костальная жилка настоящего крыла."},{"title":"Согни корпус","action":"Согни пополам по центральной пунктирной линии, цветом внутрь. Затем отогни каждое крыло наружу по его штрихпунктирной линии.","check":"Два слоя корпуса висят снизу и касаются друг друга."},{"title":"Надень скрепки на голову","action":"Надень обе скрепки на два слоя корпуса, одну поверх другой, до самого носа.","check":"Скрепки находятся внутри пунктирной рамки."},{"title":"Проверь баланс","action":"Положи крылья на два пальца под точками в кружках. Хвост опускается: добавь скрепку. Нос опускается: сдвинь скрепку назад или сними её.","check":"Бабочка держится ровно на пальцах."},{"title":"Сделай букву V","action":"Подними оба крыла в неглубокую V. Посмотри с хвоста и сравни каждый кончик с полоской.","check":"Оба кончика на одной высоте."},{"title":"Запуск и настройка","action":"Плавно толкните вперёд, нос ровно, примерно со скоростью лёгкого бега. Пикирует: поднимите оба язычка на 1–2 мм. Взмывает и зависает: выпрямите их.","check":"Поворачивает влево: чуть подними правый закрылок. Вправо: левый."}]}
